template <typename T, typename = void>
struct HasValueMember {
    static constexpr bool value = false;
};

// SFINAE specialization enabled by expression check
template <typename T>
struct HasValueMember<T,
    decltype( (void)T::Value, 0 )> // Substitution failure if T::Value invalid
{
    static constexpr bool value = true;
};

struct TypeA {};
struct TypeB { int Value = 1; };

// Usage:
// HasValueMember<TypeA>::value == false
// HasValueMember<TypeB>::value == true
